//! Tonic gRPC service implementation for the License hot path.
//!
//! Each RPC reuses the domain layer + Repository (same handlers the REST API
//! uses), so behavior is identical across transports. Auth: a Bearer token in
//! the `authorization` metadata, resolved to an account by the same
//! `tokens.get_by_hash` lookup the REST middleware uses.

// Generated by tonic-build from proto/license.proto. `include_proto!` expands
// to a module containing all message types + the service trait + server.
pub mod proto {
    tonic::include_proto!("licensev1");
}

use proto::license_service_server::LicenseService as Trait;
// Bring the generated message types into scope so the impl signatures match
// the trait (which references them unqualified from within `proto`).
use license_crypto::license_file::{issue, Algorithm, Encryption, SignatureScheme};
use license_crypto::{KeyAlgorithm, KeyPair};
use license_domain::repository::Repository;
use license_domain::{
    CullStrategy, License, LicenseId, Machine, MachineState, PolicyScheme, ResurrectionStrategy,
};
use proto::{
    ActivateRequest, CheckInRequest, CheckInResponse, CheckOutChunk, CheckOutRequest,
    DeactivateRequest, DeactivateResponse, LicenseInfo, MachineResponse, PingRequest, PingResponse,
    ValidateKeyRequest, ValidateRequest, ValidateResponse,
};
use std::pin::Pin;
use std::sync::Arc;
use std::time::Duration;
use time::OffsetDateTime;
use tokio::sync::mpsc;
use tonic::{Request, Response, Status, Streaming};

/// Type alias for the boxed stream returned by CheckOut.
type TonicStream<T> = Pin<Box<dyn tokio_stream::Stream<Item = Result<T, Status>> + Send + 'static>>;

/// Per-license validate budget: fixed window of 2000/min per key or license.
const VALIDATE_LIMIT_CAPACITY: u64 = 2000;
const VALIDATE_WINDOW_SECS: u64 = 60;
/// Max key length accepted on ValidateKey — anything longer is garbage/abuse
/// and would burn a sha256 + DB lookup before rejection.
const MAX_KEY_LEN: usize = 1024;

// Atomic fixed-window arming: INCR + EXPIRE in one round-trip. Re-arms any
// bucket whose TTL was lost to a partial failure (TTL < 0), so a limiter
// fault can never wedge it into permanent rejection.
const ARM_WINDOW_SCRIPT: &str = "
local v = redis.call('INCR', KEYS[1])
if v == 1 or redis.call('TTL', KEYS[1]) < 0 then
  redis.call('EXPIRE', KEYS[1], ARGV[1])
end
return v
";

/// A gRPC LicenseService backed by a Repository + master secret.
pub struct LicenseService {
    pub repo: Arc<dyn Repository>,
    pub master_secret: Arc<[u8; 32]>,
    limits: Option<redis::aio::ConnectionManager>,
}

impl LicenseService {
    pub fn new(repo: Arc<dyn Repository>, master_secret: Arc<[u8; 32]>) -> Self {
        Self {
            repo,
            master_secret,
            limits: None,
        }
    }

    pub fn with_limits(mut self, redis: Option<redis::aio::ConnectionManager>) -> Self {
        self.limits = redis;
        self
    }

    /// Fixed-window counter for a validate path. Fail-open: Redis absent or
    /// faulting must never block legitimate validation. Mirrors
    /// license_api::rate_limit::check (duplicated to avoid an api dep).
    async fn check_validate_limit(&self, id: &str) -> Result<(), Status> {
        let Some(mut conn) = self.limits.clone() else {
            return Ok(());
        };
        let key = limit_bucket(id);
        let count: Option<i64> = redis::Script::new(ARM_WINDOW_SCRIPT)
            .key(&key)
            .arg(VALIDATE_WINDOW_SECS)
            .invoke_async(&mut conn)
            .await
            .ok();
        let Some(count) = count else {
            return Ok(());
        };
        if count as u64 > VALIDATE_LIMIT_CAPACITY {
            // Generic on purpose: no bucket detail back to the caller.
            Err(Status::unavailable("try again later"))
        } else {
            Ok(())
        }
    }
}

fn limit_bucket(id: &str) -> String {
    format!("grpc:validate:{id}")
}

#[tonic::async_trait]
impl Trait for LicenseService {
    async fn validate(
        &self,
        req: Request<ValidateRequest>,
    ) -> Result<Response<ValidateResponse>, Status> {
        let r = req.into_inner();
        let aid = parse_uuid(&r.account_id, "account_id")?;
        let lid = parse_uuid(&r.license_id, "license_id")?;
        self.check_validate_limit(&lid.to_string()).await?;
        let license = self
            .repo
            .licenses()
            .get(license_domain::AccountId(aid), LicenseId(lid))
            .await
            .map_err(domain_to_status)?;
        let now = OffsetDateTime::now_utc();
        let (valid, detail) = match license.validate_for_use(now) {
            Ok(()) => (true, String::new()),
            Err(e) => (false, e.to_string()),
        };
        Ok(Response::new(ValidateResponse {
            valid,
            state: state_str(license.state).to_string(),
            detail,
            license: Some(to_license_info(&license)),
        }))
    }

    async fn validate_key(
        &self,
        req: Request<ValidateKeyRequest>,
    ) -> Result<Response<ValidateResponse>, Status> {
        let r = req.into_inner();
        if r.key.is_empty() {
            return Err(Status::invalid_argument("key is required"));
        }
        if r.key.len() > MAX_KEY_LEN {
            return Err(Status::invalid_argument("key exceeds maximum length"));
        }
        let key_hash = license_crypto::sha256_hex(r.key.as_bytes());
        self.check_validate_limit(&key_hash).await?;
        let license = self
            .repo
            .licenses()
            .get_by_key_hash(&key_hash)
            .await
            .map_err(|e| match e {
                // Generic by design: never echo domain details (ids, hashes)
                // back to an unauthenticated key-holder.
                license_domain::DomainError::NotFound(_)
                | license_domain::DomainError::CrossTenant(_) => {
                    Status::not_found("license not found")
                }
                other => domain_to_status(other),
            })?;
        let now = OffsetDateTime::now_utc();
        let (valid, detail) = match license.validate_for_use(now) {
            Ok(()) => (true, String::new()),
            Err(e) => (false, e.to_string()),
        };
        Ok(Response::new(ValidateResponse {
            valid,
            state: state_str(license.state).to_string(),
            detail,
            license: Some(to_license_info(&license)),
        }))
    }

    async fn activate(
        &self,
        req: Request<ActivateRequest>,
    ) -> Result<Response<MachineResponse>, Status> {
        let r = req.into_inner();
        if r.fingerprint.is_empty() {
            return Err(Status::invalid_argument("fingerprint is required"));
        }
        let aid = license_domain::AccountId(parse_uuid(&r.account_id, "account_id")?);
        let lid = LicenseId(parse_uuid(&r.license_id, "license_id")?);

        // Load license + policy to learn max_machines + heartbeat cadence.
        let license = self
            .repo
            .licenses()
            .get(aid, lid)
            .await
            .map_err(domain_to_status)?;
        let policy = self
            .repo
            .policies()
            .get(aid, license.policy_id)
            .await
            .map_err(domain_to_status)?;
        let now = OffsetDateTime::now_utc();
        license
            .validate_for_use(now)
            .map_err(|e| Status::failed_precondition(e.to_string()))?;

        // Enforce max_machines (if the fingerprint isn't already bound).
        if let Some(max) = policy.max_machines {
            let already = self
                .repo
                .machines()
                .get_by_fingerprint(aid, lid, &r.fingerprint)
                .await;
            let already_active = matches!(already, Ok(m) if m.state == MachineState::Active);
            if !already_active {
                let count = self
                    .repo
                    .machines()
                    .count_active(aid, lid)
                    .await
                    .map_err(domain_to_status)?;
                if count >= max as u64 {
                    return Err(Status::failed_precondition(format!(
                        "max_machines ({max}) reached"
                    )));
                }
            }
        }

        // Idempotent activate: if a machine with this fingerprint exists,
        // revive/refresh it; otherwise create.
        let mut machine = match self
            .repo
            .machines()
            .get_by_fingerprint(aid, lid, &r.fingerprint)
            .await
        {
            Ok(mut m) => {
                m.state = MachineState::Active;
                if !r.name.is_empty() {
                    m.name = Some(r.name.clone());
                }
                if !r.platform.is_empty() {
                    m.platform = Some(r.platform.clone());
                }
                m
            }
            Err(_) => {
                let mut m = Machine::new(aid, lid, r.fingerprint.clone());
                m.name = if r.name.is_empty() {
                    None
                } else {
                    Some(r.name.clone())
                };
                m.platform = if r.platform.is_empty() {
                    None
                } else {
                    Some(r.platform.clone())
                };
                m.core_count = if r.core_count == 0 {
                    None
                } else {
                    Some(r.core_count)
                };
                m.cull_strategy = CullStrategy::DeactivateDead;
                m.resurrection_strategy = ResurrectionStrategy::AlwaysRevive;
                m
            }
        };
        if let Some(hb) = policy.heartbeat_duration {
            machine.ping(hb);
        }
        let saved = if self
            .repo
            .machines()
            .get_by_fingerprint(aid, lid, &r.fingerprint)
            .await
            .is_ok()
        {
            self.repo
                .machines()
                .update(&machine)
                .await
                .map_err(domain_to_status)?
        } else {
            self.repo
                .machines()
                .create(&machine)
                .await
                .map_err(domain_to_status)?
        };
        Ok(Response::new(MachineResponse {
            id: saved.id.to_string(),
            license_id: saved.license_id.to_string(),
            fingerprint: saved.fingerprint,
            state: machine_state_str(saved.state).to_string(),
            next_heartbeat: saved.next_heartbeat.map(rfc3339).unwrap_or_default(),
        }))
    }

    async fn deactivate(
        &self,
        req: Request<DeactivateRequest>,
    ) -> Result<Response<DeactivateResponse>, Status> {
        let r = req.into_inner();
        let aid = license_domain::AccountId(parse_uuid(&r.account_id, "account_id")?);
        let mid = parse_uuid(&r.machine_id, "machine_id")?;
        self.repo
            .machines()
            .delete(aid, license_domain::MachineId(mid))
            .await
            .map_err(domain_to_status)?;
        Ok(Response::new(DeactivateResponse { deactivated: true }))
    }

    async fn ping(&self, req: Request<PingRequest>) -> Result<Response<PingResponse>, Status> {
        let r = req.into_inner();
        let aid = license_domain::AccountId(parse_uuid(&r.account_id, "account_id")?);
        let mid = parse_uuid(&r.machine_id, "machine_id")?;
        let mut machine = self
            .repo
            .machines()
            .get(aid, license_domain::MachineId(mid))
            .await
            .map_err(domain_to_status)?;
        // Refresh the heartbeat using the policy's cadence.
        // Load the license to find its policy_id.
        let license = self
            .repo
            .licenses()
            .get(aid, machine.license_id)
            .await
            .map_err(domain_to_status)?;
        let policy = self
            .repo
            .policies()
            .get(aid, license.policy_id)
            .await
            .map_err(domain_to_status)?;
        let hb = policy
            .heartbeat_duration
            .unwrap_or(Duration::from_secs(300));
        machine.ping(hb);
        let next = machine.next_heartbeat;
        self.repo
            .machines()
            .update(&machine)
            .await
            .map_err(domain_to_status)?;
        Ok(Response::new(PingResponse {
            alive: machine.state == MachineState::Active,
            next_heartbeat: next.map(rfc3339).unwrap_or_default(),
        }))
    }

    async fn check_in(
        &self,
        req: Request<CheckInRequest>,
    ) -> Result<Response<CheckInResponse>, Status> {
        let r = req.into_inner();
        let aid = license_domain::AccountId(parse_uuid(&r.account_id, "account_id")?);
        let lid = LicenseId(parse_uuid(&r.license_id, "license_id")?);
        let mut license = self
            .repo
            .licenses()
            .get(aid, lid)
            .await
            .map_err(domain_to_status)?;
        let policy = self
            .repo
            .policies()
            .get(aid, license.policy_id)
            .await
            .map_err(domain_to_status)?;
        let heartbeat = policy
            .heartbeat_duration
            .unwrap_or(Duration::from_secs(3600));
        license.check_in(heartbeat);
        let next = license.next_check_in;
        self.repo
            .licenses()
            .update(&license)
            .await
            .map_err(domain_to_status)?;
        Ok(Response::new(CheckInResponse {
            ok: true,
            next_check_in: next.map(rfc3339).unwrap_or_default(),
        }))
    }

    type CheckOutStream = TonicStream<CheckOutChunk>;

    async fn check_out(
        &self,
        req: Request<CheckOutRequest>,
    ) -> Result<Response<Self::CheckOutStream>, Status> {
        let r = req.into_inner();
        let aid = license_domain::AccountId(parse_uuid(&r.account_id, "account_id")?);
        let lid = LicenseId(parse_uuid(&r.license_id, "license_id")?);
        let license = self
            .repo
            .licenses()
            .get(aid, lid)
            .await
            .map_err(domain_to_status)?;
        let policy = self
            .repo
            .policies()
            .get(aid, license.policy_id)
            .await
            .map_err(domain_to_status)?;

        // Build the license-file body (same shape as the REST check-out).
        let now = OffsetDateTime::now_utc();
        let ttl = Duration::from_secs(24 * 3600);
        let body = serde_json::json!({
            "data": {
                "id": license.id.to_string(),
                "state": state_str(license.state),
                "policy_id": license.policy_id.to_string(),
                "uses": license.uses,
                "max_uses": license.max_uses,
            },
            "meta": {
                "issued": rfc3339(now),
                "expiry": rfc3339(now + ttl),
                "ttl": ttl.as_secs(),
            }
        });
        let body_bytes = serde_json::to_vec(&body).map_err(|e| Status::internal(e.to_string()))?;

        // Throwaway keypair for the same scheme (scaffold — Phase 4.x persisted
        // keys; production uses the account's SigningKey via KeyStore).
        let keypair = KeyPair::generate(key_algorithm_for(policy.scheme))
            .map_err(|e| Status::internal(e.to_string()))?;
        let aes_key =
            license_crypto::keystream::derive_aes_key(&self.master_secret[..], &r.account_id, 1);
        let algorithm = Algorithm {
            encryption: Encryption::Aes256Gcm,
            signature: SignatureScheme::Ed25519,
        };
        let cert = issue(algorithm, &keypair, "v1", &body_bytes, Some(&aes_key))
            .map_err(|e| Status::internal(e.to_string()))?;

        // Stream the PEM in chunks.
        let (tx, rx) = mpsc::channel::<Result<CheckOutChunk, Status>>(4);
        let pem = cert.pem;
        let alg_str = cert.algorithm.as_str().to_string();
        tokio::spawn(async move {
            // First chunk carries the algorithm marker.
            let chunk_size = 4096;
            let mut first = true;
            for chunk in pem.as_bytes().chunks(chunk_size) {
                let msg = CheckOutChunk {
                    data: chunk.to_vec(),
                    algorithm: if first {
                        first = false;
                        alg_str.clone()
                    } else {
                        String::new()
                    },
                };
                if tx.send(Ok(msg)).await.is_err() {
                    break;
                }
            }
        });
        let stream = tokio_stream::wrappers::ReceiverStream::new(rx);
        Ok(Response::new(Box::pin(stream)))
    }
}

// Silence the unused Streaming import (we don't accept any client streams yet).
#[allow(dead_code)]
type _UnusedStreaming = Streaming<CheckOutRequest>;

fn parse_uuid(s: &str, field: &str) -> Result<uuid::Uuid, Status> {
    uuid::Uuid::parse_str(s).map_err(|_| Status::invalid_argument(format!("invalid {field} `{s}`")))
}

#[allow(clippy::result_large_err)]
fn domain_to_status(e: license_domain::DomainError) -> Status {
    use license_domain::DomainError as E;
    match e {
        E::NotFound(_) | E::CrossTenant(_) => Status::not_found(e.to_string()),
        E::Conflict(_) => Status::already_exists(e.to_string()),
        E::Invalid(_) => Status::invalid_argument(e.to_string()),
        E::InvalidState(_) | E::PolicyViolated(_) => Status::failed_precondition(e.to_string()),
        E::Unauthorized(_) => Status::permission_denied(e.to_string()),
        E::Crypto(_) | E::Internal(_) => Status::internal(e.to_string()),
    }
}

fn state_str(s: license_domain::LicenseState) -> &'static str {
    match s {
        license_domain::LicenseState::Active => "active",
        license_domain::LicenseState::Suspended => "suspended",
        license_domain::LicenseState::Revoked => "revoked",
        license_domain::LicenseState::Expired => "expired",
    }
}

fn machine_state_str(s: MachineState) -> &'static str {
    match s {
        MachineState::Active => "active",
        MachineState::Dead => "dead",
        MachineState::Deactivated => "deactivated",
    }
}

fn key_algorithm_for(s: PolicyScheme) -> KeyAlgorithm {
    match s {
        PolicyScheme::Ed25519Sign | PolicyScheme::JwtEddsa => KeyAlgorithm::Ed25519,
        PolicyScheme::EcdsaP256Sha256 => KeyAlgorithm::EcdsaP256,
        PolicyScheme::Rsa2048PssSha256
        | PolicyScheme::Rsa2048Pkcs1v15Sha256
        | PolicyScheme::JwtRs256 => KeyAlgorithm::Rsa2048,
    }
}

fn to_license_info(l: &License) -> LicenseInfo {
    LicenseInfo {
        id: l.id.to_string(),
        account_id: l.account_id.to_string(),
        policy_id: l.policy_id.to_string(),
        uses: l.uses,
        max_uses: l.max_uses.unwrap_or(0),
        expiry: l.expiry.map(rfc3339).unwrap_or_default(),
    }
}

fn rfc3339(t: OffsetDateTime) -> String {
    t.format(&time::format_description::well_known::Rfc3339)
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;
    use license_db::{Pool, SqliteRepository};
    use license_domain::repository::Repository;
    use license_domain::{Account, License, Policy, PolicyScheme, Product};

    async fn fresh_repo() -> Arc<dyn Repository> {
        let pool = Pool::sqlite_in_memory().await.unwrap();
        Arc::new(SqliteRepository::from(pool))
    }

    // Mirrors grpc_e2e::seed — keep in sync.
    async fn seed(repo: &Arc<dyn Repository>) -> String {
        let account = Account::new("grpc-co", "gRPCCo");
        repo.accounts().create(&account).await.unwrap();
        let product = Product::new(account.id, "P");
        repo.products().create(&product).await.unwrap();
        let policy = Policy::new(account.id, product.id, "pol", PolicyScheme::Ed25519Sign);
        repo.policies().create(&policy).await.unwrap();
        let keypair =
            license_crypto::KeyPair::generate(license_crypto::KeyAlgorithm::Ed25519).unwrap();
        let signed = license_crypto::sign_license_key(
            license_crypto::KeyScheme::Ed25519,
            &keypair,
            "seed-lic",
            &account.id.to_string(),
        )
        .unwrap();
        let mut license = License::new(account.id, product.id, policy.id);
        license.key_hash = signed.key_hash.clone();
        repo.licenses().create(&license).await.unwrap();
        signed.key
    }

    #[tokio::test]
    async fn validate_key_rejects_oversize_key() {
        let svc = LicenseService::new(fresh_repo().await, Arc::new([0x42u8; 32]));
        let err = svc
            .validate_key(Request::new(ValidateKeyRequest {
                key: "x".repeat(1025),
            }))
            .await
            .unwrap_err();
        assert_eq!(err.code(), tonic::Code::InvalidArgument);
        assert_eq!(err.message(), "key exceeds maximum length");
    }

    #[tokio::test]
    async fn validate_key_still_validates_without_redis() {
        let repo = fresh_repo().await;
        let key = seed(&repo).await;
        let svc = LicenseService::new(repo, Arc::new([0x42u8; 32])).with_limits(None);
        let resp = svc
            .validate_key(Request::new(ValidateKeyRequest { key }))
            .await
            .unwrap();
        assert!(resp.into_inner().valid);
    }

    #[tokio::test]
    async fn validate_key_unknown_key_maps_to_generic_not_found() {
        let svc = LicenseService::new(fresh_repo().await, Arc::new([0x42u8; 32]));
        let err = svc
            .validate_key(Request::new(ValidateKeyRequest {
                key: "no-such-key".into(),
            }))
            .await
            .unwrap_err();
        assert_eq!(err.code(), tonic::Code::NotFound);
        assert_eq!(err.message(), "license not found");
    }

    #[test]
    fn limit_bucket_embeds_full_id() {
        // Same-millisecond UUIDv7s share their first 12 chars; truncation
        // would collapse co-created licenses into one bucket (finding I1).
        let long = "019f99f9-6063-7c02-bca9-04722c894a9c";
        assert_eq!(limit_bucket(long), format!("grpc:validate:{long}"));
        let a = "019f99f9-aaaa-7c02-bca9-04722c894a9c";
        let b = "019f99f9-bbbb-7c02-bca9-04722c894a9c";
        assert_ne!(limit_bucket(a), limit_bucket(b));
    }
}
